/** A stored vector as numbers of length 1. */
export function decodeSubjectVector(base64: string): Float32Array {
  const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
  const out = new Float32Array(bytes.length);
  let norm = 0;
  for (let i = 0; i < bytes.length; i++) {
    const q = (bytes[i]) << 24 >> 24; // the byte as a signed number
    out[i] = q;
    norm += q * q;
  }
  const scale = norm > 0 ? 1 / Math.sqrt(norm) : 0;
  for (let i = 0; i < out.length; i++) out[i] = (out[i]) * scale;
  return out;
}

/** A vector as the text stored in the generated block (what `--write` puts there). */
export function encodeSubjectVector(vector: Float32Array): string {
  let max = 0;
  for (const x of vector) max = Math.max(max, Math.abs(x));
  const scale = max > 0 ? 127 / max : 0;
  let binary = '';
  for (const x of vector) binary += String.fromCharCode(Math.round(x * scale) & 0xff);
  return btoa(binary);
}
